using System;using System.Collections.Generic;namespace Recovered.Gameplay {public static class PtlRenderSubmission {public static void Render(SoundSetupImage m,uint context,int bank,PtlRenderServices external,PtlProfiling.QueryCounter clock){var services=new PtlRenderServices();services.Camera=external.Camera;services.Call=delegate(SoundSetupImage image,uint address,uint[] values){if(address!=0x60c410)return external.Call(image,address,values);uint[] matrix=new uint[16];Array.Copy(values,4,matrix,0,16);Func<SoundSetupImage,uint,uint[],uint> children=delegate(SoundSetupImage memory,uint child,uint[] args){if(child!=0x60b5d0)return external.Call(memory,child,args);var forwarded=new List<uint>();for(int i=0;i<4;i++)forwarded.Add(args[i]);forwarded.AddRange(matrix);for(int i=5;i<10;i++)forwarded.Add(args[i]);return external.Call(memory,child,forwarded.ToArray());};PtlDrawSubmission.Submit(image,values[0],values[1],values[2],values[3],0,values[20],values[21],values[22],values[23],values[24],children);return 0;};PtlRenderCamera.Render(m,context,bank,services,clock);}}}
